# -*- coding: utf-8 -*-
"""
start_safe.py  —  запуск ботов UA ART COMPANY с защитой от TimedOut.
БЕЗ КОНСОЛИ и без правки твоих файлов.

Как включить:
  1) Загрузить этот файл в /home/Carix/   (Files -> Upload a file)
  2) Вкладка Tasks -> у задачи нажать карандаш (Edit)
     и заменить команду на:
         python3.10 /home/Carix/start_safe.py
  3) Нажать Restart / галочку.

Ни один твой файл не меняется. Чтобы вернуть как было — просто верни
в задаче прежнюю команду: python3.10 /home/Carix/run_all.py

Что делает:
  - поднимает таймауты Telegram (5 c -> 60/120/180 c);
  - повторяет отправку до 4 раз при обрыве связи;
  - не присылает владельцу «Сбой во внутреннем боте» на сетевые таймауты;
  - после этого обычным образом запускает run_all.py.
"""

import os
import sys
import time
import asyncio
import functools
import logging
import runpy
import shutil

BASE = "/home/Carix"
TARGET = os.path.join(BASE, "run_all.py")

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s %(levelname)s %(name)s: %(message)s",
)
log = logging.getLogger("start_safe")

# --- таймауты и повторы ----------------------------------------------------

READ_TIMEOUT = 60
WRITE_TIMEOUT_TEXT = 60
WRITE_TIMEOUT_MEDIA = 180
CONNECT_TIMEOUT = 30
POOL_TIMEOUT = 15

RETRIES = 3
PAUSE = 1.5

TEXT_METHODS = (
    "send_message",
    "edit_message_text",
    "edit_message_caption",
    "edit_message_reply_markup",
    "edit_message_media",
    "delete_message",
)

# нажатие кнопки подтверждается за секунды — повторять нельзя
SILENT_METHODS = ("answer_callback_query",)

MEDIA_METHODS = (
    "send_photo",
    "send_video",
    "send_document",
    "send_audio",
    "send_animation",
    "send_media_group",
)


def _bump(value, floor):
    """None значит «без ограничения» — не трогаем. Маленькое значение поднимаем."""
    if value is None:
        return None
    try:
        return max(float(value), float(floor))
    except (TypeError, ValueError):
        return floor


def patch_request_timeouts():
    """Заводские 5 секунд в HTTPXRequest заменяем на человеческие."""
    from telegram.request import HTTPXRequest

    orig = HTTPXRequest.__init__
    if getattr(orig, "_ns_wrapped", False):
        return

    @functools.wraps(orig)
    def inner(self, *args, **kwargs):
        # ГЛАВНОЕ: по умолчанию соединение с Telegram всего одно.
        # Пока уходит альбом фото, все остальные запросы стоят в очереди
        # и умирают по таймауту. Даём 16 параллельных соединений.
        try:
            size = int(kwargs.get("connection_pool_size") or 1)
        except (TypeError, ValueError):
            size = 1
        kwargs["connection_pool_size"] = max(size, 16)

        kwargs["read_timeout"] = _bump(kwargs.get("read_timeout", 5), READ_TIMEOUT)
        kwargs["write_timeout"] = _bump(kwargs.get("write_timeout", 5), WRITE_TIMEOUT_TEXT)
        kwargs["connect_timeout"] = _bump(kwargs.get("connect_timeout", 5), CONNECT_TIMEOUT)
        kwargs["pool_timeout"] = _bump(kwargs.get("pool_timeout", 1), POOL_TIMEOUT)
        try:
            return orig(self, *args, **kwargs)
        except TypeError:
            # версия библиотеки не знает таких аргументов — идём как есть
            for k in (
                "read_timeout", "write_timeout", "connect_timeout",
                "pool_timeout", "connection_pool_size",
            ):
                kwargs.pop(k, None)
            return orig(self, *args, **kwargs)

    inner._ns_wrapped = True
    HTTPXRequest.__init__ = inner
    log.info("таймауты соединения подняты")


def _wrap_send(orig, is_media, errors):
    TimedOut, NetworkError, RetryAfter = errors

    @functools.wraps(orig)
    async def inner(self, *args, **kwargs):
        args, kwargs = fix_split_text(orig.__name__, args, kwargs)
        if orig.__name__ == "send_media_group":
            args, kwargs = _dopisat_video(args, kwargs)
        kwargs.setdefault("read_timeout", READ_TIMEOUT)
        kwargs.setdefault("connect_timeout", CONNECT_TIMEOUT)
        kwargs.setdefault(
            "write_timeout", WRITE_TIMEOUT_MEDIA if is_media else WRITE_TIMEOUT_TEXT
        )

        last = None
        for attempt in range(1, RETRIES + 1):
            try:
                # тот же самый файл уже уходил — отправляем по id, без заливки
                sent_id = None
                if orig.__name__ == "send_document":
                    raw = _doc_bytes(kwargs.get("document") or (args[1] if len(args) > 1 else None))
                    if raw:
                        sig = "doc:" + hashlib.md5(raw).hexdigest()
                        cached = _cache_get(sig)
                        if cached:
                            kwargs.pop("document", None)
                            if len(args) > 1:
                                args = (args[0],) + (cached.decode("utf-8"),) + tuple(args[2:])
                            else:
                                kwargs["document"] = cached.decode("utf-8")
                            log.info("файл взят из кэша, без перезаливки")
                        else:
                            sent_id = sig

                result = await orig(self, *args, **kwargs)

                if orig.__name__ == "send_document":
                    try:
                        if sent_id and getattr(result, "document", None):
                            _cache_put(sent_id, result.document.file_id.encode("utf-8"))
                    except Exception:
                        pass
                    asyncio.create_task(_videos_after_html(self, result))
                return result
            except RetryAfter as e:
                last = e
                wait = float(getattr(e, "retry_after", 3)) + 1
                log.warning("флуд-контроль на %s, ждём %.0f c", orig.__name__, wait)
                await asyncio.sleep(wait)
            except (TimedOut, NetworkError) as e:
                last = e
                if attempt == RETRIES:
                    break
                wait = PAUSE * attempt
                log.warning(
                    "сеть подвела на %s, попытка %d из %d, пауза %.0f c",
                    orig.__name__, attempt, RETRIES, wait,
                )
                await asyncio.sleep(wait)
            except TypeError:
                for k in ("read_timeout", "write_timeout", "connect_timeout"):
                    kwargs.pop(k, None)
                return await orig(self, *args, **kwargs)
        raise last

    inner._ns_wrapped = True
    return inner


async def _videos_after_html(bot, message):
    """HTML собирается только с фото — видео досылаем следом в чат."""
    try:
        doc = getattr(message, "document", None)
        name = getattr(doc, "file_name", "") or ""
        found = re.search(r"(UA-\d+)\.html$", name, re.IGNORECASE)
        if not found:
            return
        number = found.group(1)

        cols = set(_car_columns())
        if "videos" not in cols or "auto_number" not in cols:
            return
        rows = _rows(
            "SELECT videos FROM cars WHERE auto_number = ? LIMIT 1", (number,)
        )
        if not rows:
            return
        videos = _ids(rows[0].get("videos"))
        if not videos:
            log.info("у карточки %s видео нет", number)
            return
        if time.time() - VIDEO_V_ALBOME.get(number, 0) < 120:
            log.info("видео по %s уже внутри карточки — не дублируем", number)
            return

        from telegram import InputMediaVideo

        chat_id = message.chat_id
        await bot.send_message(chat_id, "Видео по карточке %s — %d шт." % (number, len(videos)))
        for i in range(0, len(videos), 10):
            chunk = videos[i:i + 10]
            if len(chunk) == 1:
                await bot.send_video(chat_id, chunk[0])
            else:
                await bot.send_media_group(chat_id, [InputMediaVideo(v) for v in chunk])
            await asyncio.sleep(ALBUM_PAUSE)
        log.info("досланы видео по карточке %s: %d", number, len(videos))
    except Exception as e:
        log.warning("не удалось дослать видео: %r", e)


# --- кэш: не качаем и не заливаем одно и то же дважды ----------------------

import hashlib

CACHE_DIR = os.path.join(BASE, ".ns_cache")


def _cache_path(key):
    safe = hashlib.md5(str(key).encode("utf-8")).hexdigest()
    return os.path.join(CACHE_DIR, safe + ".bin")


def _cache_get(key):
    try:
        path = _cache_path(key)
        if os.path.exists(path):
            with open(path, "rb") as fh:
                return fh.read()
    except Exception:
        pass
    return None


def _cache_put(key, data):
    try:
        os.makedirs(CACHE_DIR, exist_ok=True)
        with open(_cache_path(key), "wb") as fh:
            fh.write(data)
    except Exception as e:
        log.warning("кэш не записался: %r", e)


def patch_download_cache():
    """Каждый кадр скачивается из Telegram один раз за всё время."""
    from telegram import File

    for name in ("download_as_bytearray", "download_to_memory"):
        orig = File.__dict__.get(name)
        if orig is None or getattr(orig, "_ns_wrapped", False):
            continue

        @functools.wraps(orig)
        async def inner(self, *args, __orig=orig, __name=name, **kwargs):
            key = getattr(self, "file_unique_id", None) or getattr(self, "file_id", "")
            data = _cache_get(key) if key else None

            if __name == "download_as_bytearray":
                if data is not None:
                    return bytearray(data)
                result = await __orig(self, *args, **kwargs)
                if key and result:
                    _cache_put(key, bytes(result))
                return result

            # download_to_memory(out) — пишем в переданный буфер
            out = args[0] if args else kwargs.get("out")
            if data is not None and out is not None:
                out.write(data)
                return None
            result = await __orig(self, *args, **kwargs)
            try:
                if key and out is not None:
                    pos = out.tell()
                    out.seek(0)
                    _cache_put(key, out.read())
                    out.seek(pos)
            except Exception:
                pass
            return result

        inner._ns_wrapped = True
        setattr(File, name, inner)
    log.info("кэш скачанных кадров включён")


def _doc_bytes(document):
    """Достаёт байты собранного файла, если это возможно."""
    if isinstance(document, (bytes, bytearray)):
        return bytes(document)
    data = getattr(document, "input_file_content", None)
    if isinstance(data, (bytes, bytearray)):
        return bytes(data)
    return None


# --- видео внутри карточки, сразу под фото ---------------------------------
#
# Telegram разрешает класть фото и видео в один альбом. Ловим последний
# альбом карточки и дописываем в него ролики: они оказываются внутри
# галереи, под фотографиями. Ограничение в 20 МБ здесь не работает —
# файл уже лежит в Telegram, бот его не скачивает.

_KARTY = {"kogda": 0.0, "spisok": []}
VIDEO_V_ALBOME = {}          # номер карточки -> когда видео уже ушли
NASTROYKA = {}               # чат -> шаг настройки помощника


def _karty():
    """Список карточек с медиа, обновляется раз в минуту."""
    if time.time() - _KARTY["kogda"] < 60 and _KARTY["spisok"]:
        return _KARTY["spisok"]
    try:
        cols = set(_car_columns())
        nuzhno = [c for c in ("auto_number", "photos", "videos", "hidden_photos")
                  if c in cols]
        if "photos" not in nuzhno or "videos" not in nuzhno:
            return []
        rows = _rows("SELECT %s FROM cars" % ", ".join(nuzhno))
        spisok = []
        for d in rows:
            hidden = set(_ids(d.get("hidden_photos")))
            foto = [p for p in _ids(d.get("photos")) if p not in hidden]
            video = _ids(d.get("videos"))
            if foto and video:
                spisok.append({
                    "nomer": d.get("auto_number") or "",
                    "foto": foto,
                    "video": video,
                })
        _KARTY["spisok"] = spisok
        _KARTY["kogda"] = time.time()
        return spisok
    except Exception as e:
        log.warning("не прочитал карточки: %r", e)
        return []


def _dopisat_video(args, kwargs):
    """Если это последний альбом фото карточки — дописываем в него видео."""
    try:
        media = kwargs.get("media")
        iz_kwargs = media is not None
        if media is None and len(args) > 1:
            media = args[1]
        if not media or not isinstance(media, (list, tuple)) or len(media) >= 10:
            return args, kwargs

        ids = []
        for m in media:
            fid = getattr(m, "media", None)
            tip = getattr(m, "type", "")
            if not isinstance(fid, str) or tip not in ("photo", ""):
                return args, kwargs          # альбом не из чистых фото
            ids.append(fid)
        if not ids:
            return args, kwargs

        for karta in _karty():
            if ids[-1] != karta["foto"][-1]:
                continue                     # не последний альбом карточки
            if not set(ids) & set(karta["foto"]):
                continue
            nomer = karta["nomer"]

            from telegram import InputMediaVideo
            mesto = 10 - len(media)
            roliki = karta["video"][:mesto]
            if not roliki:
                return args, kwargs

            novoe = list(media) + [InputMediaVideo(v) for v in roliki]
            VIDEO_V_ALBOME[nomer] = time.time()
            log.info("видео вложено в карточку %s: %d", nomer, len(roliki))
            if iz_kwargs:
                kwargs["media"] = novoe
            else:
                args = (args[0], novoe) + tuple(args[2:])
            return args, kwargs
    except Exception as e:
        log.warning("не вложил видео в альбом: %r", e)
    return args, kwargs


def _wrap_silent(orig):
    """answer_callback_query живёт секунды: не повторяем и не роняем обработчик."""

    @functools.wraps(orig)
    async def inner(self, *args, **kwargs):
        kwargs.setdefault("read_timeout", 10)
        kwargs.setdefault("write_timeout", 10)
        kwargs.setdefault("connect_timeout", 10)
        kwargs.setdefault("pool_timeout", 10)
        try:
            return await orig(self, *args, **kwargs)
        except TypeError:
            for k in ("read_timeout", "write_timeout", "connect_timeout", "pool_timeout"):
                kwargs.pop(k, None)
            try:
                return await orig(self, *args, **kwargs)
            except Exception:
                return True
        except Exception as e:
            log.warning("не подтвердили нажатие кнопки, идём дальше: %r", e)
            return True

    inner._ns_wrapped = True
    return inner


ALBUM_PAUSE = 0.3


def patch_card_html_budget():
    """Делаем HTML-файл лёгким: он собирается долго только из-за веса."""
    try:
