def patch_bot_methods():
    """Повторы отправки при обрыве связи."""
    from telegram import Bot
    from telegram.error import TimedOut, NetworkError, RetryAfter

    errors = (TimedOut, NetworkError, RetryAfter)

    # ВАЖНО: ExtBot наследуется от Bot. Если обернуть оба класса,
    # повторы вкладываются друг в друга: 4 попытки превращаются в 16.
    # Поэтому Bot трогаем только там, где ExtBot своего метода не имеет.
    ext = None
    try:
        from telegram.ext import ExtBot
        ext = ExtBot
    except Exception:
        ext = None

    n = 0
    for name in TEXT_METHODS + MEDIA_METHODS + SILENT_METHODS:
        target = None
        if ext is not None and name in ext.__dict__:
            target = ext
        elif name in Bot.__dict__:
            target = Bot
        if target is None:
            continue
        orig = target.__dict__.get(name)
        if orig is None or getattr(orig, "_ns_wrapped", False):
            continue
        if name in SILENT_METHODS:
            setattr(target, name, _wrap_silent(orig))
        else:
            setattr(target, name, _wrap_send(orig, name in MEDIA_METHODS, errors))
        n += 1
    log.info("защищено методов отправки: %d", n)


def patch_error_handlers():
    """Сетевые таймауты не уходят владельцу как «Сбой во внутреннем боте»."""
    from telegram.ext import Application
    from telegram.error import TimedOut, NetworkError

    orig = Application.add_error_handler
    if getattr(orig, "_ns_wrapped", False):
        return

    def filtered(callback):
        @functools.wraps(callback)
        async def inner(update, context):
            err = getattr(context, "error", None)
            if isinstance(err, (TimedOut, NetworkError)):
                log.warning("сетевая ошибка не показана владельцу: %r", err)
                return
            return await callback(update, context)

        inner._ns_filtered = True
        return inner

    @functools.wraps(orig)
    def inner(self, callback, block=True, *args, **kwargs):
        if not getattr(callback, "_ns_filtered", False):
            callback = filtered(callback)
        try:
            return orig(self, callback, block, *args, **kwargs)
        except TypeError:
            return orig(self, callback)

    inner._ns_wrapped = True
    Application.add_error_handler = inner
    log.info("фильтр сетевых ошибок включён")


# --- условия 50/50 для авто, которое уже в Грузии --------------------------
#
# Пока авто едет — схема 50 % по договору / 50 % по прибытии в Грузию.
# Когда авто в Грузии — этой строки быть не должно, там предоплата 500 $.

import re
import sqlite3
import shutil

# признаки того, что речь про авто, уже стоящее в Грузии
GEO_MARKERS = ("Предоплата", "Авто в Грузии", "в Грузии")

# предложение про 50/50 — в любых написаниях (50%, 50 %, 50 процентов)
SPLIT_RE = re.compile(
    r"[^.\n!]*50\s*%[^.\n!]*(?:договор|прибыт)[^.\n!]*[.!]?",
    re.IGNORECASE,
)


def clean_split(text):
    """Убирает фразу про 50/50, если авто уже в Грузии."""
    if not text or "50" not in text:
        return text
    if not any(m in text for m in GEO_MARKERS):
        return text
    if "Предоплата" not in text and "Авто в Грузии" not in text:
        return text
    new = SPLIT_RE.sub("", text)
    if new == text:
        return text
    new = re.sub(r"[ \t]{2,}", " ", new)
    new = re.sub(r"\n{3,}", "\n\n", new)
    new = re.sub(r"[ \t]+\n", "\n", new)
    return new.strip()


def fix_split_text(method_name, args, kwargs):
    """Чистит text/caption прямо перед отправкой."""
    try:
        for key in ("text", "caption"):
            if key in kwargs and isinstance(kwargs[key], str):
                kwargs[key] = clean_split(kwargs[key])
        # send_message(chat_id, text) — текст может идти вторым по счёту
        if method_name in ("send_message", "edit_message_text") and len(args) >= 2:
            if isinstance(args[1], str):
                args = list(args)
                args[1] = clean_split(args[1])
                args = tuple(args)
    except Exception as e:
        log.warning("не удалось почистить текст: %r", e)
    return args, kwargs


def db_clean_split():
    """Разово вычищает фразу 50/50 из описаний машин, стоящих в Грузии."""
    db = os.path.join(BASE, "crm.db")
    if not os.path.exists(db):
        return
    try:
        con = sqlite3.connect(db)
        cur = con.cursor()
        cols = [r[1] for r in cur.execute("PRAGMA table_info(cars)").fetchall()]
        if "condition_text" not in cols:
            con.close()
            return

        keys = ["rowid", "condition_text"]
        for extra in ("status", "stage"):
            if extra in cols:
                keys.append(extra)
        rows = cur.execute("SELECT %s FROM cars" % ", ".join(keys)).fetchall()

        changed = []
        for row in rows:
            data = dict(zip(keys, row))
            text = data.get("condition_text") or ""
            if "50" not in text:
                continue
            status = str(data.get("status") or "")
            stage = data.get("stage")
            in_georgia = ("Грузи" in status) or (
                isinstance(stage, int) and stage >= 3
            )
            if not in_georgia:
                continue
            new = SPLIT_RE.sub("", text)
            new = re.sub(r"\n{3,}", "\n\n", new).strip()
            if new != text:
                changed.append((new, data["rowid"]))

        if changed:
            shutil.copy2(db, db + ".bak_split")
            cur.executemany(
                "UPDATE cars SET condition_text = ? WHERE rowid = ?", changed
            )
            con.commit()
            log.info("описание почищено от 50/50 у карточек: %d", len(changed))
        con.close()
    except Exception as e:
        log.warning("чистка базы не удалась: %r", e)


# --- свой экран «Как видит покупатель» -------------------------------------
#
# Работает независимо от кнопок в cars_ui: команда /pokaz в CRM-боте
# показывает список карточек, по нажатию рисует карточку ровно так,
# как её видит покупатель — фото сверху, текст, видео снизу.

import json

PHONE = "[N]"
WHATSAPP = "[URL]"
ADDRESS = "Киев, улица Победы 20"
MAPS = "[URL]"
PREPAY = "500 $"
DAYS_AFTER_PAY = 14

CAR_FIELDS = (
    "auto_number", "brand", "model", "year", "vin", "fuel", "engine_cc",
    "gearbox", "drive", "mileage_km", "color", "condition_text", "diag_link",
    "status", "sea_container", "price_uah", "published", "eta_manual",
    "photos", "videos", "hidden_photos",
)


def _rows(query, params=()):
    db = os.path.join(BASE, "crm.db")
    con = sqlite3.connect(db)
    con.row_factory = sqlite3.Row
    try:
        return [dict(r) for r in con.execute(query, params).fetchall()]
    finally:
        con.close()


def _car_columns():
    db = os.path.join(BASE, "crm.db")
    con = sqlite3.connect(db)
    try:
        return [r[1] for r in con.execute("PRAGMA table_info(cars)").fetchall()]
    finally:
        con.close()


def _ids(value):
    """Достаёт список file_id из колонки, в каком бы виде она ни хранилась."""
    if not value:
        return []
    if isinstance(value, (list, tuple)):
        items = list(value)
    else:
        text = str(value).strip()
        items = None
        if text.startswith("[") or text.startswith("{"):
            try:
                data = json.loads(text)
                if isinstance(data, dict):
                    data = list(data.values())
                items = data
            except Exception:
                items = None
        if items is None:
            items = re.split(r"[\s,;|]+", text)
    out = []
    for it in items:
        if isinstance(it, dict):
            it = it.get("file_id") or it.get("id") or ""
        it = str(it).strip().strip('"').strip("'")
        if len(it) > 20:
            out.append(it)
    return out


def _money(value):
    try:
        n = int(float(value))
    except (TypeError, ValueError):
        return "—"
    return "{:,}".format(n).replace(",", " ") + " $"


def _dash(value):
    value = "" if value is None else str(value).strip()
    return value if value else "—"


def client_text(car):
    """Текст карточки глазами покупателя."""
    status = str(car.get("status") or "")
    in_georgia = "Грузи" in status

    title = " ".join(x for x in [car.get("brand"), car.get("model")] if x) or "Автомобиль"
    lines = []
    lines.append("UA ART COMPANY LLC")
    lines.append("")
    lines.append("%s %s" % (title, _dash(car.get("year"))))
    lines.append("Номер: %s" % _dash(car.get("auto_number")))
    lines.append("VIN: %s" % _dash(car.get("vin")))
    lines.append("")
    lines.append("ХАРАКТЕРИСТИКИ")
    lines.append("Топливо: %s" % _dash(car.get("fuel")))
    lines.append("Объём: %s" % _dash(car.get("engine_cc")))
    lines.append("КПП: %s" % _dash(car.get("gearbox")))
    lines.append("Привод: %s" % _dash(car.get("drive")))
    lines.append("Пробег: %s" % _dash(car.get("mileage_km")))
    lines.append("Цвет: %s" % _dash(car.get("color")))
    if car.get("diag_link"):
        lines.append("Диагностика: %s" % car["diag_link"])
    if car.get("condition_text"):
        lines.append("")
        lines.append("ОПИСАНИЕ")
        lines.append(str(car["condition_text"]).strip())
    lines.append("")
    lines.append("СТАТУС")
    lines.append(_dash(status))
    if not in_georgia and car.get("sea_container"):
        lines.append("Контейнер: %s" % car["sea_container"])
    lines.append("")
    lines.append("ЦЕНА")
    lines.append(_money(car.get("price_uah")))
    lines.append("")
    lines.append("УСЛОВИЯ")
    lines.append("Доставка, растаможка и сертификация включены в стоимость.")
    if in_georgia:
        lines.append("Предоплата %s — авто закрепляется за вами." % PREPAY)
        lines.append("Срок прибытия после оплаты — %d дней." % DAYS_AFTER_PAY)
    else:
        lines.append("Оплата 50 % по договору и 50 % по прибытии в Грузию.")
    lines.append("")
    lines.append("%s · %s" % (PHONE, ADDRESS))
    return "\n".join(lines)


async def _send_client_card(bot, chat_id, car):
    from telegram import InputMediaPhoto, InputMediaVideo
    from telegram import InlineKeyboardButton, InlineKeyboardMarkup

    hidden = set(_ids(car.get("hidden_photos")))
    photos = [p for p in _ids(car.get("photos")) if p not in hidden]
    videos = _ids(car.get("videos"))

    for i in range(0, len(photos), 10):
        chunk = photos[i:i + 10]
        if len(chunk) == 1:
            await bot.send_photo(chat_id, chunk[0])
        else:
            await bot.send_media_group(chat_id, [InputMediaPhoto(p) for p in chunk])
        await asyncio.sleep(ALBUM_PAUSE)

    keyboard = InlineKeyboardMarkup([[
        InlineKeyboardButton("WhatsApp", url=WHATSAPP),
        InlineKeyboardButton("Карта", url=MAPS),
    ]])
    await bot.send_message(chat_id, client_text(car), reply_markup=keyboard)

    for i in range(0, len(videos), 10):
        chunk = videos[i:i + 10]
        if len(chunk) == 1:
            await bot.send_video(chat_id, chunk[0])
        else:
            await bot.send_media_group(chat_id, [InputMediaVideo(v) for v in chunk])
        await asyncio.sleep(ALBUM_PAUSE)


